#!/usr/bin/env bash
#
# Resolve aerospike-server.docker's master tip to a commit sha, and print it.
#
# Why this exists rather than letting a caller pass `master` through to
# actions/checkout: that ref is checked out THREE times, independently, across two
# workflow runs -- `versions` reads the default lineage set from it, `context` generates
# the Dockerfile from it, and `test-images` runs test.sh from it. `context` and
# `test-images` are separated by three multi-arch builds, an hour or more, and the
# dispatcher's checkout is in a different run entirely. A floating ref can therefore
# resolve to a different commit at each one: the image gets generated by commit A and
# validated by commit B's test harness, and every job passes.
#
# So a caller that wants the tip resolves it ONCE, here, and pins the sha for the rest of
# the run. The 40-hex requirement downstream is unchanged; only where the value comes
# from changes.
#
# ls-remote and not a clone: this needs one ref, the repo is public, and the answer is a
# single round trip with no working tree.
#
# Optional env (for tests; the defaults are the real repo):
#   DOCKER_REPO_URL     repository to query
#   DOCKER_REPO_BRANCH  branch whose tip to take (default: master)
#
# Usage: docker_repo_tip.sh

set -euo pipefail

url=${DOCKER_REPO_URL:-https://github.com/aerospike/aerospike-server.docker}
branch=${DOCKER_REPO_BRANCH:-master}

if ! out=$(git ls-remote "$url" "refs/heads/${branch}" 2>&1); then
    echo "::error::could not reach ${url} to resolve ${branch}: ${out}" >&2
    exit 1
fi

# An ls-remote that matches nothing exits 0 with no output, so the shape check below is
# what turns "that branch does not exist" into a failure rather than an empty ref.
sha=$(awk 'NR == 1 { print $1 }' <<<"$out")
if [[ ! "$sha" =~ ^[0-9a-f]{40}$ ]]; then
    echo "::error::${url} has no ${branch} branch, or it did not resolve to a commit sha (got '${sha}')." >&2
    exit 1
fi

echo "$sha"
